/* Types */
/**
 *  The trust ask: what this plane will put in force, in the words the operator reads.
 * 
 *  **In the app the prompt IS the prompt** (ADR 0035). charter's CLI asks by printing a second
 *  command to type, because `util.py` has nothing that reads stdin and a hook blocked on stdin
 *  hangs a turn — a constraint about the CLI and about nothing else. Here there is a window
 *  and a person looking at it, so the question is asked where the answer is given.
 */
export type Ask = {
	/**
	 *  The plane charter resolved, which is what the approval is recorded against.
	 * 
	 *  Shown, and not merely carried: a picker pointed at a subdirectory opens the plane above
	 *  it, and an operator approving a directory they did not choose is the whole failure this
	 *  dialog exists to prevent, arrived at from the friendly end.
	 */
	path: string,
	/**
	 *  What it contributes. It goes back to [`approve_plane`] untouched, and that is what
	 *  makes the approval an answer to the question that was asked.
	 */
	contributes: PlaneContribution,
	/**
	 *  Empty when nothing has approved this plane. Otherwise every way it now differs from
	 *  what WAS approved, in charter's own words (`machine::Change`'s own `Display`).
	 */
	changes: string[],
	/**  Whether this is a first approval rather than a re-ask, so the dialog can say which. */
	first: boolean,
};

/**  Everything the chat's gauge draws. Every part is absent when charter does not know it. */
export type ChatUsage = {
	/**  `ctx NN%`: how full the context window was at the last turn that said. */
	context: Percent | null,
	/**  `cache NN%`: the share of the last turn's input served from cache. */
	cache: Percent | null,
	rebuilds: Rebuilds | null,
};

/**  Where a chat is working, when it is working in a piece. */
export type ChatWorktree = {
	workspace: string,
	repo: string,
	piece: string,
	branch: string | null,
	wired: boolean,
	stale: boolean,
};

/**  What the doctor said, and what it was asked with. */
export type DoctorReport = {
	/**  Every row, in the order `charter doctor` prints them. */
	rows: DoctorRow[],
	/**  Whether the harness profiles were probed — the full doctor, not the preflight. */
	full: boolean,
	/**
	 *  The `PATH` this process has, which is the one every row that looks for a program was
	 *  answered with.
	 * 
	 *  **Not a row, and not the doctor's**: `charter doctor` prints no such line, and this is
	 *  not dressed as one. It is here for the incident this module exists for — a Finder
	 *  launch hands the app a four-directory `PATH`, and a built-in profile the doctor does
	 *  not list (it lists one only when it finds its program) makes no sense until you can see
	 *  the `PATH` it was looked for on. `None` when the process has none at all, which is
	 *  itself the answer.
	 */
	path: string | null,
};

/**  One doctor row: the four fields `charter doctor --json` prints, and one it does not. */
export type DoctorRow = {
	name: string,
	status: DoctorStatus,
	detail: string,
	hint: string,
	/**
	 *  Whether this build runs this check at all ([`Row::deferred`]).
	 * 
	 *  `false` is about twenty rows on every plane, each a WARN that says *not checked (…not
	 *  ported…)*. They are drawn, because a doctor that dropped them would read as those
	 *  problems being fixed — but a summary that COUNTED them would draw a warning count that
	 *  never moves, and the one real warning among them would be invisible on its first day.
	 */
	checked: boolean,
};

/**  A row's verdict, as the window draws it. */
export type DoctorStatus = "ok" | "warn" | "fail";

/**
 *  The question charter asks before an extension contributes anything.
 * 
 *  A mirror of [`extension::Prompt`] rather than the thing itself, because `charter-core` never
 *  depends on the app and the app's wire types are generated into TypeScript.
 * 
 *  **The two sentences travel with it rather than being written in the dialog.** That is the
 *  point of carrying them: a window that composed its own words about what an extension can
 *  reach could drift kinder than the truth one edit at a time, and the truth here is
 *  uncomfortable enough that kinder is the likely direction.
 */
export type ExtensionAsk = {
	/**  The id the record is keyed by, and the id the yes is recorded against. */
	id: string,
	/**  What to call it, as its own manifest does. */
	name: string,
	/**
	 *  Where it is. Shown and not merely carried: an extension is approved at a path, and one
	 *  re-installed from another directory is a different question.
	 */
	path: string,
	/**  Every contribution it declares, in charter's own words, one line each. */
	declares: string[],
	/**
	 *  The fingerprint of the bytes that were read to build this question. It goes back to
	 *  [`approve_extension`] untouched, so the yes is for what was shown.
	 */
	fingerprint: string,
	/**  Whether this is a first ask rather than a re-ask. */
	first: boolean,
	/**
	 *  `extension::RUNS_AS_YOU` — that a plugin runs with the operator's own access and that
	 *  the list above is a declaration, not a limit.
	 */
	runs_as_you: string,
	/**
	 *  `extension::FINGERPRINTED` — that the fingerprint catches a change and is not a
	 *  boundary.
	 */
	fingerprint_note: string,
};

/**  One row of "what has contributed what to this window". */
export type ExtensionRow = {
	id: string,
	/**  What to call it: its manifest's name when charter could read one, else its id. */
	name: string,
	path: string,
	/**  `approved`, `new` or `changed`. */
	standing: string,
	/**
	 *  The themes it is contributing **right now** — empty unless it is approved, so the row
	 *  says what is in force rather than what was asked for.
	 */
	themes_in_force: string[],
	/**  Every contribution it declares, whether or not any of it is in force. */
	declares: string[],
	/**
	 *  Why charter could not read it, when it could not. A row that contributes nothing says
	 *  why rather than going quiet.
	 */
	refused: string | null,
	/**  The question to ask about it, when there is one to ask. */
	ask: ExtensionAsk | null,
};

/**  One theme an approved extension is contributing, as the window receives it. */
export type ExtensionTheme = {
	/**  The extension it came from, so the window can say whose theme it is drawing. */
	extension: string,
	/**  What to call it, as the manifest does. */
	name: string,
	/**
	 *  The file's **text**, unparsed.
	 * 
	 *  **The vocabulary is `theme.ts`'s and the parser is `theme.ts`'s**, and this crate
	 *  deliberately does not grow a second one. `TOKENS` is the closed vocabulary charter owns
	 *  (ADR 0041 property 1) and `load` is the parse-and-re-emit that keeps a theme's bytes out
	 *  of a stylesheet (property 4); both are already written and already tested. A Rust parser
	 *  here would be a second vocabulary, and two vocabularies drift — which is property 1
	 *  turning into a lie by accident rather than by decision.
	 * 
	 *  It is the text the fingerprint was taken over, handed on rather than fetched again.
	 */
	text: string,
};

/**  How a number reads, as the window colours it — `charter_core::usage::Tone`. */
export type GaugeTone = "ok" | "warn" | "bad";

/**
 *  What has contributed what to this window — charter ADR 0041's item 2, and the thing every
 *  later decision about extensions is read off.
 */
export type InstalledExtensions = {
	/**
	 *  charter's own themes, which are compiled into the window and are never asked about.
	 *  Listed so that the answer to "what is contributing" is one list rather than one per
	 *  source.
	 */
	built_in_themes: string[],
	extensions: ExtensionRow[],
	/**
	 *  Why the record could not be read, when it could not — in which case nothing an
	 *  extension declares is in force and `extensions` is empty.
	 */
	unreadable: string | null,
	/**  Rows the record held and charter dropped, with the reason for each. */
	dropped: string[],
};

/**
 *  What a launch had to go on, and what came of it.
 * 
 *  **Three states, and none of them is an error.** The app has to come up holding no plane at
 *  all and stay useful — that is what an opener attaches to — and "there is no plane where you
 *  launched me" is a different thing to tell an operator from "you have not opened one yet".
 *  A window double-clicked from the dock has a working directory of `/` and is the second;
 *  `charter` run in a directory that is in no plane is the first.
 * 
 *  They are told apart by shape rather than by reading a sentence: `plane` set is a plane in
 *  hand, `from` set without it is a directory that is in no plane, and neither is a launch
 *  that was given nothing to go on.
 */
export type Launch = {
	/**  The plane this launch opened, and the id every command for it names. */
	plane: PlaneId | null,
	/**
	 *  The directory the launch was given, when it could be read. A HINT and nothing more:
	 *  it is resolved once, here, and no command consults the working directory again.
	 */
	from: string | null,
	/**  Why no plane was opened, in the resolver's own words. */
	why: string | null,
};

/**  What a merge did, for the window to report. */
export type Merged = {
	branch: string,
	was: string,
	now: string,
};

/**
 *  The event the window listens for. One chat, its state, whether it is asking for you.
 * 
 *  **The plane travels with it, and that is not decoration.** Every plane numbers its chats
 *  from one, so a window holding two of them would be told "session 3 is waiting" twice about
 *  two different chats. The pair is the identity; one half of it is a guess.
 */
export type Moved = {
	plane: PlaneId,
	session: number,
	state: string,
	needs_you: boolean,
	/**
	 *  Every chat asking for you, so the queue is never assembled from a series of events
	 *  the window might have missed one of.
	 */
	queue: number[],
	/**
	 *  When this chat last moved, as a count of moves on its plane's board — bigger is
	 *  more recent. `charter_core::state::Board::moved_at` is the whole definition.
	 * 
	 *  **The window cannot work this out for itself, which is why it rides an event that
	 *  already fires.** Charter ADR 0039 sorts the chat strip's overflow menu by last
	 *  activity, and nothing in the window knows when a chat did anything: the strip is
	 *  `tabs.order`, which is an opening order, and the needs-you queue is oldest-first,
	 *  which is a different fact. An order computed in the window would also restart at
	 *  every launch and disagree between two windows on one plane, where this one is the
	 *  board's and the board is the plane's.
	 * 
	 *  A count rather than a clock, and a `u32` rather than a `u64`: both are argued where
	 *  the field is produced, and the second is not negotiable here — `specta` refuses to
	 *  export a `u64` and the app panics at startup in a debug build when one is reached
	 *  for.
	 */
	moved_at: number,
};

/**  One chat the app has open, as the UI draws it and as the quit warning lists it. */
export type OpenChat = {
	session: number,
	name: string,
	cwd: string | null,
	/**  The harness it runs, by the word the plane calls it — or none for a shell. */
	harness: string | null,
	/**  Whether it is the chat to show: at a launch, the one that was in front at the quit. */
	in_front: boolean,
	/**  The conversation it was resumed by, where it was. The UI says which happened. */
	resumed: string | null,
	/**  Why it is a new chat rather than the one it was, where it is. */
	fresh: string | null,
	/**  The harness profile it started on, where it started on one. */
	profile: string | null,
	/**  The persona it adopted. */
	persona: string | null,
	/**  What its harness cannot tell charter, said on the chat — none where it tells all. */
	unreported: string | null,
	/**
	 *  Whether the operator pinned it (charter ADR 0039). It rides the plane's own app
	 *  record, so a pinned chat comes back pinned at the next launch.
	 */
	pinned: boolean,
};

/**
 *  What came of asking to open a plane: it is open, or there is a question to answer first.
 * 
 *  Two nullable fields rather than a tagged union, and told apart by shape the way
 *  `plane_at_launch` is: exactly one of them is ever set, and a window that reads `plane`
 *  first cannot accidentally treat an ask as an open.
 */
export type Opened = {
	/**  The plane, once it is open. Null when the operator has to be asked first. */
	plane: PlaneId | null,
	/**  What to ask them. Null when the plane is open. */
	ask: Ask | null,
};

/**  One open todo. There is no state field: a closed todo is a deleted file (ADR 0004). */
export type PanelTodo = {
	/**  The file stem, which is what a todo is closed by. */
	slug: string,
	title: string,
	/**  The date the todo was written, as the file records it. */
	stamp: string,
};

/**  Everything the panels can draw without running git. */
export type Panels = {
	/**
	 *  The workspace this is about, so a late answer can be matched to the ask and an answer
	 *  for a workspace that is no longer focused can be thrown away.
	 */
	workspace: string,
	/**  The clones on disk, by name, in the order the directory lists them. */
	repos: string[],
	/**  Repos `workspace.json` names that are not cloned here. Membership, not presence. */
	absent: string[],
	/**
	 *  What charter would not look at, by name and reason. Shown, never dropped: a row that
	 *  is missing is otherwise merely missing.
	 */
	refused: ([string, string])[],
	todos: PanelTodo[],
	/**
	 *  Why the todos could not be read, where they could not. A store that is a link out of
	 *  the plane is refused, and "no todos" would be the wrong thing to draw for it.
	 */
	todos_refused: string | null,
	/**  The plane's personas, and the one a chat started here would adopt. */
	personas: string[],
	persona: string | null,
};

/**  One percentage on the gauge, and the tone its threshold gives it. */
export type Percent = {
	/**
	 *  A whole percentage. `i32`, because `specta` refuses the core's `i64`, and a recorded
	 *  value outside it is not a percentage anyone could read anyway.
	 */
	value: number,
	tone: GaugeTone,
};

/**  One piece, as the window shows it. */
export type Piece = {
	piece: string,
	path: string,
	branch: string | null,
	/**
	 *  Whether charter's harness layer is in this tree.
	 * 
	 *  Since M1.x a worktree charter cuts is wired as it is cut, so `false` now means a tree
	 *  cut by plain git, one whose wire did not land, or a plane with no layer to carry. The
	 *  row still says so, because a chat in such a tree runs without the plane's ask/deny
	 *  rules, without its persona's agents and without `$CHARTER_HARNESS` — and starting one
	 *  there is what writes the layer or refuses.
	 */
	wired: boolean,
	/**  Set when git still has a registration whose directory is gone. */
	stale: boolean,
};

/**
 *  What the operator has pinned in one project (charter ADR 0039, stored per ADR 0040).
 * 
 *  The project's own pin and its pinned workspaces come from the machine store; a pinned
 *  CHAT is not here, because a chat pin rides that chat's own record and reaches the window
 *  on `OpenChat::pinned` with the chat it is about.
 */
export type Pins = {
	/**  Whether this project itself is pinned. */
	project: boolean,
	/**
	 *  Its pinned workspaces that still exist, in the plane's own order.
	 * 
	 *  The plane's order and never the pin's: a pin says WHICH workspaces come first, not in
	 *  what order they do, so two operators who pin the same two see the same arrangement.
	 */
	workspaces: string[],
	/**
	 *  Pins that no longer name a workspace on the plane — renamed, or removed.
	 * 
	 *  **Named rather than dropped silently**, and never drawn as a workspace: a window that
	 *  drew one would be offering a workspace the plane does not have. This is ADR 0034's
	 *  own hazard for a trust entry keyed on a path, one scope down.
	 */
	missing: string[],
};

/**
 *  What a plane would contribute, as the trust prompt draws it — **and the exact value the
 *  operator's approval is checked against.**
 * 
 *  A mirror of [`machine::Contribution`] rather than the thing itself, because `charter-core`
 *  never depends on the app and the app's wire types are generated into TypeScript. Each of
 *  the four maps travels as pairs in the map's own order, which is `BTreeMap`'s and therefore
 *  sorted, so a value that comes back from the window compares against one taken from disk
 *  without either side having to sort anything.
 */
export type PlaneContribution = {
	/**
	 *  Each plugin the plane's committed settings enable, and what they enable it as. These
	 *  run inside the operator's harness.
	 */
	plugins: ([string, string])[],
	/**
	 *  Each environment variable those settings set, and its value. ADR 0022 measured where
	 *  these land: a variable set on the harness process reaches the shell the model runs.
	 */
	env: ([string, string])[],
	/**
	 *  One line per chat the plane's reopen record would start on a program of its own — the
	 *  program, its arguments and its directory, as the record names them.
	 */
	starts: ([string, string])[],
	/**
	 *  One line per chat that record would start on one of THIS machine's harness profiles.
	 *  Drawn beside the rest and weighed differently: the record chooses which of the
	 *  operator's own profiles runs, and `profiletrust` gates what any of them runs.
	 */
	profiles: ([string, string])[],
};

/**
 *  Which plane something is acting for.
 * 
 *  It is the plane's root as the registry resolved it, and it is minted by [`Planes::open`]
 *  alone — a caller hands one back, it never spells one. Two spellings of one directory would
 *  otherwise be two entries in the registry holding two boards for one plane on disk, which
 *  is the "acting on the wrong plane" defect wearing a different hat.
 */
export type PlaneId = string;

/**
 *  One row of the profile picker: what it runs, where charter read it, and what pressing
 *  Enter on it would do.
 */
export type ProfileRow = {
	name: string,
	kind: string,
	/**
	 *  The environment and the command as one line a person reads, already contained: a
	 *  profile is a file a chat can write, and a control byte in it must never redraw a row.
	 */
	shown: string,
	/**  `built-in` or `charter.local.toml`. */
	source: string,
	/**  The row the picker starts on. It launches nothing by itself. */
	is_default: boolean,
	/**
	 *  `new` or `changed` when this profile's command must be shown and approved before it
	 *  runs; absent when charter has already recorded running exactly this.
	 */
	approval: string | null,
};

/**  The prefix rebuilds this conversation has paid for (`↻N 696k`). */
export type Rebuilds = {
	count: number,
	/**
	 *  The total, already spelled as charter spells tokens (`696k`, `1.2M`), so the window
	 *  and the frame's panel cannot come to round it differently.
	 */
	cost: string,
	tone: GaugeTone,
};

/**
 *  One plane this machine remembers, as the opener draws it.
 * 
 *  **When it was last opened is not here**, though the store holds it: it is what puts the
 *  list in order, and the list is already in that order when it arrives. Carrying it would be
 *  carrying a `u64` across the wire for nobody to draw — and specta refuses to export one at
 *  all, to avoid the precision loss a JavaScript number would silently have. A row that says
 *  "three days ago" can have it as a number this side of that limit, when there is a row that
 *  says it.
 */
export type RecentPlane = {
	/**  The plane's root: the path it was approved under and the path it will be opened by. */
	path: string,
	/**
	 *  What to call it in a list — the directory's own name. Two projects can share one, so
	 *  the path is shown beside it and is what identifies the row.
	 */
	name: string,
	/**
	 *  Whether the operator has approved this plane before.
	 * 
	 *  **Not a promise that opening it will not ask.** Whether it still contributes what they
	 *  approved is a question about the plane's own files, and it is asked when the plane is
	 *  opened. This is only what the store holds, which costs no disk at all — sixty-four
	 *  rows each reading a settings file and a reopen record, to label a list, is a launch
	 *  spent answering a question the next click answers properly.
	 */
	approved: boolean,
};

/**  What the opener has to offer, and everything it had to leave out to offer it. */
export type Recents = {
	/**  Most recently opened first. */
	planes: RecentPlane[],
	/**
	 *  One line per row charter would not offer: a plane that has moved or gone, and an entry
	 *  the store itself would not take back.
	 * 
	 *  **Never an error, and never a dialog.** ADR 0034: the file is a convenience and the
	 *  plane is the truth, so a launch that showed a modal about a memory stick that is not
	 *  plugged in would be worse than the thing it was reporting.
	 */
	dropped: string[],
	/**
	 *  Why this machine remembers nothing at all, in charter's own words — a platform charter
	 *  keeps no store on (ADR 0031: `0600` has no expression on Windows, so the guard refuses
	 *  rather than degrades), or a store charter would not read. Null when it does remember.
	 * 
	 *  The app is a working app either way. It just opens every project by picking it.
	 */
	forgetful: string | null,
};

/**  One clone's git state, and what the forge cache last recorded for its branch. */
export type RepoState = {
	name: string,
	/**  The branch the checkout is on, where it is on one. */
	branch: string | null,
	/**  Whether that branch holds no commit yet. */
	unborn: boolean,
	/**  The commit HEAD sits on when it is on no branch. */
	detached: string | null,
	upstream: string | null,
	ahead: number,
	behind: number,
	/**  Changed files git is tracking. */
	tracked: number,
	/**  Files git is not tracking. */
	untracked: number,
	/**
	 *  Why charter could not read the tree. Every count above is zero when this is set, and
	 *  it means charter does not know — not that the tree is clean.
	 */
	unreadable: string | null,
	/**  What the forge cache last recorded, one of the seven states charter knows. */
	ci: string | null,
	change: number | null,
	sigil: string | null,
	/**  How long ago the cache entry was written, which is how old this answer is. */
	fetched_seconds_ago: number | null,
	/**
	 *  Why there is nothing from the forge to show. Absent when something was fetched, even
	 *  when what was fetched named no pipeline.
	 */
	not_fetched: string | null,
};

/**  Every clone of one workspace, as the panels draw them. */
export type RepoStates = {
	workspace: string,
	repos: RepoState[],
	/**
	 *  Why the forge cache was not read at all, where it was not. Reported once for the
	 *  listing rather than repeated on every row.
	 */
	cache_refused: string | null,
};

/**
 *  What a cold launch puts back: the projects that were open, and what it would not take back.
 * 
 *  **A project that has moved or is gone is dropped with a line saying so, never an error
 *  dialog** (ADR 0033). The window draws those lines where the operator is standing, the way
 *  the opener draws a recents row that went.
 */
export type Restore = {
	/**  The projects to open again, left to right as the tabs were. */
	planes: string[],
	/**
	 *  Which of them was in front, as an index into `planes` after the drops. Null when there
	 *  is nothing to put back.
	 */
	active: number | null,
	/**  One line per project charter would not take back. */
	dropped: string[],
};

/**
 *  The whole left-hand side: every workspace with its chats, and the focused workspace's
 *  persona and todos.
 */
export type Sidebar = {
	root: string,
	workspaces: SidebarWorkspace[],
	/**  The plane's personas, and the one a new chat here would adopt. */
	personas: string[],
	persona: string | null,
	/**  Chats whose directory is in no workspace, so the sidebar can still show them. */
	unfiled: OpenChat[],
};

/**
 *  One workspace as the sidebar draws it: what it is for, what it still means to do, and the
 *  chats working in it.
 */
export type SidebarWorkspace = {
	name: string,
	/**  Where the workspace is, so a chat can be started in it. */
	path: string,
	vision: string,
	todos: string[],
	chats: OpenChat[],
};

/**  Everything the picker draws, read from the plane when it is opened. */
export type StartOptions = {
	profiles: ProfileRow[],
	/**
	 *  Profiles charter read and will not use, by name and reason, so a row that is missing
	 *  is never merely missing.
	 */
	refused: ([string, string])[],
	personas: string[],
	/**  The plane's `[persona] default`, which is the persona row the picker starts on. */
	persona: string | null,
	/**
	 *  Set when git would carry `charter.local.toml`: every declared profile is refused
	 *  until it is fixed, and this is the one fix for that state.
	 */
	ignore_fix: string | null,
	/**
	 *  Whether this plane declares no profiles of its own. The built-ins still start, and
	 *  the picker says so rather than looking empty or broken.
	 */
	declares_none: boolean,
};

/**
 *  A chat that started: its session, and the one line to say if charter wired its profile
 *  on the way.
 */
export type Started = {
	session: number,
	wired: string | null,
};

/**
 *  A view a pane has open, and what its terminal has to match to show the session as it is:
 *  the size the screen was drawn for, so what was wrapped stays wrapped, and how much history
 *  the core is keeping, so the pane keeps the same.
 */
export type Watching = {
	view: number,
	columns: number,
	rows: number,
	scrollback: number,
};

/**
 *  What a window is holding, as it says so itself.
 * 
 *  One struct rather than two arguments, so that the tabs and the tab in front cannot be sent
 *  separately and disagree — and because a `Vec<PlaneId>` keeps its own name here, where a
 *  plane inside an `Option` argument does not.
 */
export type WindowTabs = {
	/**  The projects this window holds, left to right as its tabs show them. */
	planes: PlaneId[],
	/**
	 *  Which tab is in front. Null is the opener — the window is holding projects the
	 *  operator is not looking at, or holding none at all.
	 */
	active: number | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

